using System.Reflection;
using System.Text.RegularExpressions;

namespace Linq2GraphQL.Generator;

/// <summary>
/// Standalone mode: instead of depending on the Linq2GraphQL.Client packages, the generated client carries
/// its own copy of the runtime under <c>&lt;namespace&gt;.Runtime</c>. Clients generated by different
/// generator versions can then be used in the same app, because each one brings the runtime it was
/// generated against. The runtime source is embedded in the generator at build time.
/// </summary>
internal static class StandaloneRuntime
{
    /// <summary>
    /// The output folder the runtime is written to. The generator owns it: it is cleared before every run,
    /// so files removed from the runtime do not linger.
    /// </summary>
    public const string DirectoryName = "Runtime";

    /// <summary>
    /// Written into <see cref="DirectoryName"/> in standalone mode. Its presence is what marks a Runtime
    /// folder as the generator's to clear.
    /// </summary>
    public const string InfoFileName = "RuntimeInfo.cs";

    private const string ResourcePrefix = DirectoryName + "/";
    private const string SubscriptionsPrefix = ResourcePrefix + "Subscriptions/";
    private const string AgentPrefix = ResourcePrefix + "AI/";

    private static readonly Regex RuntimeNamespace = new(@"\bLinq2GraphQL\.Client\b", RegexOptions.Compiled);

    private static readonly string[] ClientPackages = ["Microsoft.Extensions.Caching.Memory", "Microsoft.Extensions.Http"];
    private static readonly string[] SubscriptionsPackages = ["Websocket.Client"];
    private static readonly string[] AgentPackages = ["GraphQL-Parser", "Microsoft.Extensions.AI.Abstractions"];

    /// <summary>
    /// The runtime project has ImplicitUsings enabled, the project the copy lands in might not.
    /// </summary>
    private static readonly string[] ImplicitUsings =
    [
        "System", "System.Collections.Generic", "System.IO", "System.Linq", "System.Net.Http", "System.Threading",
        "System.Threading.Tasks"
    ];

    public static string Version { get; } =
        typeof(StandaloneRuntime).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()
            ?.InformationalVersion.Split('+')[0] ?? "unknown";

    public static string GetRuntimeNamespace(string namespaceName) => namespaceName + ".Runtime";

    /// <summary>
    /// Points every reference to the runtime packages' namespaces at the copy.
    /// </summary>
    public static string RewriteNamespaces(string content, string namespaceName) =>
        RuntimeNamespace.Replace(content, GetRuntimeNamespace(namespaceName));

    /// <summary>
    /// The packages the copied runtime needs, with the versions it was built against.
    /// </summary>
    public static IReadOnlyList<(string Name, string Version)> GetPackages(bool includeSubscriptions, bool includeAgent) =>
        ClientPackages
        .Concat(includeSubscriptions ? SubscriptionsPackages : [])
        .Concat(includeAgent ? AgentPackages : [])
        .Select(e => (e, PackageVersions.All.GetValueOrDefault(e, "unknown")))
        .ToList();

    /// <summary>
    /// The runtime files: Client always, Subscriptions with subscriptions, and the agent tools
    /// (Linq2GraphQL.Client.AI) for a client generated in agent mode.
    /// </summary>
    public static IEnumerable<FileEntry> GetFiles(string namespaceName, bool includeSubscriptions, bool includeAgent)
    {
        var assembly = typeof(StandaloneRuntime).Assembly;

        // RecursiveDir in the resource name uses the build machine's path separator.
        var resources = assembly.GetManifestResourceNames()
            .Select(e => (Resource: e, Path: e.Replace('\\', '/')))
            .Where(e => e.Path.StartsWith(ResourcePrefix, StringComparison.Ordinal))
            .Where(e => includeSubscriptions || !e.Path.StartsWith(SubscriptionsPrefix, StringComparison.Ordinal))
            .Where(e => includeAgent || !e.Path.StartsWith(AgentPrefix, StringComparison.Ordinal))
            .OrderBy(e => e.Path, StringComparer.Ordinal);

        foreach (var (resource, path) in resources)
        {
            using var stream = assembly.GetManifestResourceStream(resource);
            using var reader = new StreamReader(stream);
            var source = reader.ReadToEnd().TrimStart('﻿');

            yield return new FileEntry
            {
                DirectoryName = Path.GetDirectoryName(path).Replace('\\', '/'),
                FileName = Path.GetFileName(path),
                Content = Header + MissingImplicitUsings(source) + RewriteNamespaces(source, namespaceName)
            };
        }

        yield return new FileEntry
        {
            DirectoryName = DirectoryName, FileName = InfoFileName, Content = InfoFile(namespaceName, includeSubscriptions, includeAgent)
        };
    }

    private const string Header = """
        //---------------------------------------------------------------------
        // <auto-generated/>
        // Copy of the Linq2GraphQL runtime, written by the Linq2GraphQL generator
        // in standalone mode. Please don't edit this file - regenerate instead.
        // The runtime version is in RuntimeInfo.cs.
        // Github:https://github.com/linq2graphql/linq2graphql.client
        //---------------------------------------------------------------------
        #nullable disable

        """;

    private static string MissingImplicitUsings(string source)
    {
        var missing = ImplicitUsings
            .Where(e => !Regex.IsMatch(source, $@"^\s*using {Regex.Escape(e)};", RegexOptions.Multiline))
            .Select(e => $"using {e};\n");

        return string.Concat(missing);
    }

    private static string InfoFile(string namespaceName, bool includeSubscriptions, bool includeAgent)
    {
        var packages = string.Join("\n", GetPackages(includeSubscriptions, includeAgent)
            .Select(e => $"/// <item><description>{e.Name} {e.Version}</description></item>"));

        return $$"""
            //---------------------------------------------------------------------
            // <auto-generated/>
            // Written by the Linq2GraphQL generator in standalone mode.
            // Please don't edit this file - regenerate instead.
            //---------------------------------------------------------------------

            namespace {{GetRuntimeNamespace(namespaceName)}};

            /// <summary>
            /// The Linq2GraphQL runtime this copy was taken from. It needs these packages:
            /// <list type="bullet">
            {{packages}}
            /// </list>
            /// </summary>
            public static class RuntimeInfo
            {
                public const string Version = "{{Version}}";
            }

            """;
    }
}
